</code></pre> <pre><code>import { html, ReactiveElement } from 'cami'

class CamiCounter extends ReactiveElement {
  count: number = 0

  template(): ReturnType&lt;typeof html&gt; {
      return html`
        &lt;button @click=${() =&gt; this.count--} aria-label="Decrease"&gt;−&lt;/button&gt;
        &lt;output&gt;${this.count}&lt;/output&gt;
        &lt;button @click=${() =&gt; this.count++} aria-label="Increase"&gt;+&lt;/button&gt;
      `
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'cami-counter': CamiCounter
  }
}

customElements.define('cami-counter', CamiCounter)
</code></pre> <p>Class fields become reactive after the element connects. Updating <code>count</code> schedules a render. The <code>html</code> template updates only the changed DOM parts.</p>

