      &lt;button @click=${() =&gt; this.handleAddTodo()} ?disabled=${mutation.status === 'pending'}&gt;Add&lt;/button&gt;
      ${mutation.error ? html`&lt;p role="alert"&gt;${mutation.error}&lt;/p&gt;` : ''}
